"""Summarise actual prompt readbacks and instruction receipts, with honest state labels."""
import hashlib
import html
import json
import re
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from pathlib import Path

HERE = Path(__file__).parent
def read(name):
    return json.loads((HERE / name).read_text(encoding="utf-8"))

baseline = read("automations-before.json")
immediate = [read(row["directory"] + ".verification.json") for row in baseline if row["data"].get("status") == "ACTIVE"]
final = read("automation-final-verification.json")
receipts = read("running-chat-instruction-receipts.json")
threads = read("active-chat-snapshot.json")
filters = read("filter-extension-receipt.json")
assert len(immediate) == 12
assert all(v["prompt_exact"] and v["preserved_controls"] for v in immediate)
assert all(not v["changed_fields"] and v["status"] == "PAUSED" for v in final["paused"])
assert all(v["exclusion_rule_present"] and v["prompt_exact"] for v in final["active"])
assert len(receipts) == 5 and all(v.get("instruction_receipt_seen") for v in receipts)
assert {r["thread_id"] for r in receipts} == {t["id"] for t in threads["threads"]}
assert all(hashlib.sha256(Path(v["path"]).read_bytes()).hexdigest() == v["sha256"] for v in filters)
concurrent = [v for v in final["active"] if not v["preserved_controls"]]
assessment = {"task": "Propagate intelligent search exclusions to running chats and active automations without interruptions", "decision": "FAIL", "reason": "Administrative propagation of the already-recorded orphan-search diagnosis; no distinct reader-interest development beyond that passing technical story.", "evidence": ["running-chat-instruction-receipts.json", "automation-final-verification.json", "filter-inheritance-verification.json", "../orphan-scan-cause-20261102-01a19a0f/cause-report.html"], "related_story": "The earlier technical diagnosis remains PASS with its existing named article continuation and media blocker; this configuration follow-through is not a new article."}
report = {
    "owner_chat": "01a19a0f-2359-7830-8a2f-263f78c8a55a",
    "completed_at": datetime.now(timezone.utc).isoformat(),
    "request": "Ensure currently running chats and automations pick up generated-storage exclusions without interrupting their work",
    "outcome": "Five active chats received the refreshed shared rule at normal instruction boundaries; all twelve ACTIVE automation prompts were updated and read back; fifty-six PAUSED automations were unchanged. Parent rgignore inheritance and current temporary environment exclusions were verified with tiny local fixtures.",
    "running_chats": [{"thread_id": r["thread_id"], "title": next(t["title"] for t in threads["threads"] if t["id"] == r["thread_id"]), "instruction_received": True, "receipt_times": [m["at"] for m in r["matches"] if m["classification"] == "instruction_receipt"], "reported_use": r.get("explicit_applied_record_seen", False)} for r in receipts],
    "receipt_limit": "Receipt proves the rule reached each chat's context. Only the Syn chat also retained an explicit applied record during this audit; individual later search behaviour is not universally certified.",
    "automations": {"active_prompt_updates": 12, "immediate_exact_readbacks": immediate, "paused_unchanged": 56, "final_verification": final, "concurrent_changes": concurrent, "concurrent_change_note": "Music platform monitoring's cadence changed after this task's immediate readback, while its exclusion prompt remained exact. That independent later cadence is preserved; no rollback or schedule correction was attempted. Every update performed by this task independently passed the prompt/updated_at-only comparison."},
    "default_filters": filters,
    "filter_test": read("filter-inheritance-verification.json"),
    "interruption_controls": {"chat_messages_sent": 0, "threads_created_or_woken": 0, "threads_interrupted": 0, "processes_stopped": 0, "restarts": 0, "render_or_upload_state_mutations": 0, "automation_run_requested": False},
    "private_coordination": "An owner-specific private record carries the result and limits; its existence is not counted as a chat receipt.",
    "limits": ["Already-running native scans do not retroactively reload ignore rules; this task did not stop or restart productive processes.", "The filters apply to new ordinary ripgrep discovery, including nested repositories. Explicit paths, ignore overrides and other tools remain governed by the shared scope/lifecycle rule.", "Updated automation prompts govern future scheduler inputs. No new automation run was forced to demonstrate the change."],
    "documentation_media": {"included": "Fresh generated coverage diagram from verified receipt counts", "omitted": "Screenshots and video add no proof to API/configuration readbacks and would expose unrelated active work. No interface behaviour was changed or recorded."},
    "blogworthiness": assessment,
}
(HERE / "propagation-report.json").write_text(json.dumps(report, indent=2), encoding="utf-8")
(HERE / "blogworthiness.json").write_text(json.dumps(assessment, indent=2), encoding="utf-8")
coord = {"owner": report["owner_chat"], "at": report["completed_at"], "intended_recipients": [r["thread_id"] for r in receipts] + [r["data"].get("target_thread_id") for r in baseline if r["data"].get("status") == "ACTIVE" and r["data"].get("target_thread_id")], "scope": "Search exclusions propagation; apply at natural task boundaries without interrupting work", "report": str(HERE / "propagation-report.json"), "paths": [v["path"] for v in filters] + [r"Z:\My Songs\AGENTS.md", r"Z:\My Songs\.codex-relocated-home\AGENTS.md"], "findings": ["All five active chats have actual refreshed-instruction receipts", "All twelve active automation prompt updates were independently read back; all fifty-six paused records stayed unchanged", "Parent rgignore inheritance inside a nested repository boundary verified; .build-tmp, .smoke-venv and other generated temporary trees now excluded", "Retain full yielded-command metadata and verify owned search exit before handoff"], "ownership": "Only shared discovery policy/default filters and active automation prompt text; no source/version ownership claimed", "approval_state": "Direct user request; supported automation updates and exact filter writes completed", "conflicts": "Concurrent Music platform monitoring cadence adjustment preserved after immediate prompt-only verification", "handoff_status": "Complete propagation; no reply, wakeup, interruption or restart required. Receipt and actual later use remain distinct."}
(HERE / "coordination-record.json").write_text(json.dumps(coord, indent=2), encoding="utf-8")
svg = '''<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="250" viewBox="0 0 1000 250" role="img" aria-labelledby="t d"><title id="t">Search exclusion propagation coverage</title><desc id="d">Five running chats received the instructions, twelve active automation prompts were verified, and fifty-six paused automations remained unchanged.</desc><rect width="1000" height="250" fill="#f5f8fc"/><g font-family="Arial,sans-serif" fill="#172842"><text x="28" y="38" font-size="22" font-weight="bold">Verified without stopping work</text><g fill="#e2f0e8"><rect x="28" y="63" width="296" height="128" rx="12"/><rect x="352" y="63" width="296" height="128" rx="12"/><rect x="676" y="63" width="296" height="128" rx="12"/></g><g font-size="42" font-weight="bold"><text x="54" y="116">5 / 5</text><text x="378" y="116">12 / 12</text><text x="702" y="116">56 / 56</text></g><g font-size="17"><text x="54" y="151">Running chats: rule received</text><text x="378" y="151">Active prompts: read back</text><text x="702" y="151">Paused records: unchanged</text></g><text x="28" y="227" font-size="13" fill="#53647c">Generated diagram from 2 November 2026 receipts. Rule receipt is distinct from proof of every later search.</text></g></svg>'''
ET.fromstring(svg)
(HERE / "propagation-coverage.svg").write_text(svg, encoding="utf-8")
rows = "".join(f"<tr><td>{html.escape(r['title'])}</td><td>Received {html.escape(', '.join(r['receipt_times']))}</td><td>{'Explicit applied record also found' if r['reported_use'] else 'Receipt verified; later use not separately certified'}</td></tr>" for r in report["running_chats"])
body = f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Search exclusion propagation</title><style>body{{font:17px/1.55 system-ui,sans-serif;max-width:1080px;margin:40px auto;padding:0 24px;color:#18263c}}img{{width:100%;height:auto}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{padding:10px;border-bottom:1px solid #cad4df;text-align:left;vertical-align:top}}a{{color:#174aa1}}.note{{color:#52647d}}</style><h1>Search exclusions reached the running work</h1><p>{html.escape(report['outcome'])}</p><img src="propagation-coverage.svg" alt="Coverage diagram showing five active chat receipts, twelve prompt readbacks and fifty-six paused records unchanged"><p class="note">Fresh generated diagram from actual saved receipts; no live interface capture or universal behaviour claim.</p><h2>Running chats</h2><table><tr><th>Chat</th><th>Refreshed instruction receipt (UTC/GMT)</th><th>Evidence level</th></tr>{rows}</table><p>No chat messages, wakeups, interruptions, process stops or restarts were used. The app delivered the changed shared instructions during normal work. Private coordination records are additional discoverable context and are not counted as receipt evidence.</p><h2>Automations and filters</h2><p>Every active prompt update immediately passed an exact content readback and a comparison allowing only prompt/update-time changes. All parsed fields of the 56 paused automation records remain identical. A later independent Music platform monitoring cadence change was observed and preserved; this task did not revert another owner's work.</p><p>The default filters now also cover the temporary build and smoke-test environments used by current work. A small C: fixture verified parent <code>.rgignore</code> inheritance inside a nested repository boundary while retaining source, tests and documentation. No Z: tree scan was used.</p><p class="note">Already-running native commands keep their existing search plan. New ordinary ripgrep discovery sees the filters; explicit paths, ignore overrides and PowerShell recursion require the shared scope rule. No future scheduler run was forced.</p><h2>Evidence</h2><p><a href="propagation-report.json">Structured report</a> · <a href="running-chat-instruction-receipts.json">Five instruction receipts</a> · <a href="automation-final-verification.json">Automation state comparison</a> · <a href="filter-inheritance-verification.json">Nested repository filter test</a> · <a href="filter-extension-receipt.json">Filter readbacks</a></p><p>The <a href="https://learn.chatgpt.com/docs/agent-configuration/agents-md">official instruction-discovery documentation</a> describes instruction loading at run start. This report relies on actual per-chat refreshed-message receipts, rather than assuming that editing a file establishes live adoption.</p><h2>Blogworthiness: FAIL</h2><p>{html.escape(assessment['reason'])} The <a href="../orphan-scan-cause-20261102-01a19a0f/cause-report.html">earlier technical diagnosis</a> keeps its passing story assessment and existing continuation.</p></html>'''
(HERE / "propagation-report.html").write_text(body, encoding="utf-8")
for link in re.findall(r'(?:href|src)="([^"]+)"', body):
    if not link.startswith("https://"):
        assert (HERE / link).exists(), link
print(json.dumps({"report": str(HERE / "propagation-report.html"), "chats_received": 5, "automation_prompt_readbacks": 12, "paused_unchanged": 56, "diagram_xml_valid": True, "local_links_resolve": True, "concurrent_control_drift_preserved": [r['id'] for r in concurrent]}))
